<template><div class="space-y-4 p-4"><h1 class="text-xl font-bold text-slate-800">提交报价</h1><form class="m-card space-y-3" @submit.prevent="submit"><select v-model="form.request_id" class="m-input" required><option value="">Request</option><option v-for="x in pings" :key="x.id" :value="x.id">{{ x.title }}</option></select><select v-model="form.supplier_listing_id" class="m-input"><option value="">No catalog item</option><option v-for="x in listings" :key="x.id" :value="x.id">{{ x.title }}</option></select><input v-model.number="price" class="m-input" type="number" min="0" step="0.01" required placeholder="Price"/><input v-model="form.currency" class="m-input" maxlength="3"/><textarea v-model="notes" class="m-input" placeholder="Terms"/><p v-if="error" class="text-xs text-red-600">{{ error }}</p><button class="m-btn-primary">Submit offer</button></form></div></template>
<script setup lang="ts">definePageMeta({middleware:['auth']});const route=useRoute();const api=useCommerce();const pings=ref<any[]>([]);const listings=ref<any[]>([]);const price=ref(0);const notes=ref('');const error=ref('');const form=reactive({request_id:String(route.query.request_id||''),supplier_listing_id:'',currency:'EUR'});async function submit(){try{await api.submitSupplierOffer(form.request_id,{supplier_listing_id:form.supplier_listing_id||null,price_minor:Math.round(price.value*100),currency:form.currency,terms_json:{notes:notes.value}});await navigateTo('/supplier/offers')}catch(e:any){error.value=e?.data?.detail||e?.message}}onMounted(async()=>{pings.value=(await api.listSupplierPings()).items;listings.value=(await api.listSupplierListings('active')).items})</script>
